<script lang="ts">
  import { team } from '../stores/team.svelte.ts';
  import { game } from '../../gameManager.js';
  import { useGameLanguageTick } from '../lib/useGameLanguageTick.svelte.ts';
  import type { GameRuntime } from '../types/game.js';
  import StorageFiltersBar from './StorageFiltersBar.svelte';
  import StorageSortBar from './StorageSortBar.svelte';
  import StorageGrid from './StorageGrid.svelte';
  import {
    buildStorageRoster,
    DEFAULT_STORAGE_FILTERS,
    type StorageFilterState,
  } from '../lib/storageRoster.js';
  import { GameEventType as Evt } from '../bus/events.js';
  import { useFacadeSubscription } from '../lib/useFacadeSubscription.ts';
  import { computeStorageUltimateSlotPickTooltipScale } from '../lib/ultimateSlotPreview.ts';

  const { trackGameLanguage } = useGameLanguageTick();

  function t(key: string, fallback: string, params?: Record<string, string | number>): string {
    trackGameLanguage();
    const gm = game as GameRuntime | null;
    if (!gm?.t) return fallback;
    let got = gm.t(key, params);
    if (!got || got === key) got = fallback;
    if (params) {
      for (const [k, v] of Object.entries(params)) {
        got = got.replace(`{${k}}`, String(v));
      }
    }
    return got;
  }

  let modalFilters = $state<StorageFilterState>({ ...DEFAULT_STORAGE_FILTERS });
  let rosterTick = $state(0);

  useFacadeSubscription([Evt.STORAGE_CHANGED, Evt.TEAM_CHANGED], () => {
    rosterTick += 1;
  });

  let pickCandidates = $derived.by(() => {
    rosterTick;
    trackGameLanguage();
    const gm = game as GameRuntime | null;
    if (!gm) return [];
    return buildStorageRoster(gm, modalFilters).creatures.filter(
      (c) => c.source === 'storage' && c.draggable,
    );
  });

  let pickShowEmptyFiltered = $derived.by(() => {
    rosterTick;
    const gm = game as GameRuntime | null;
    if (!gm) return false;
    const totalStorage = gm.storage?.length ?? 0;
    return pickCandidates.length === 0 && totalStorage > 0;
  });

  let bonus = $derived(team.ultimateSlotBonus);
  let transferPct = $derived(team.ultimateSlotTransferPercent);

  let pickTooltipScale = $derived.by(() => {
    rosterTick;
    transferPct;
    const gm = game as GameRuntime | null;
    if (!gm) return computeStorageUltimateSlotPickTooltipScale(null, 0.01);
    const rate = typeof gm.getUltimateSlotTransferRate === 'function'
      ? gm.getUltimateSlotTransferRate()
      : 0.01;
    return computeStorageUltimateSlotPickTooltipScale(gm, rate);
  });

  $effect(() => {
    if (!team.ultimateSlot) {
      modalFilters = { ...DEFAULT_STORAGE_FILTERS };
    }
  });
</script>

<div class="stats-content ultimate-slot-modal-content" data-action="stopPropagation" data-action-stop>
  <div class="stats-header">
    <h2 id="ultimateSlotTitleLabel">{t('ultimateSlot.title', 'Slot ultime')}</h2>
    <button type="button" class="stats-close" data-action="closeUltimateSlotModal">&#10005;</button>
  </div>

  <p class="ultimate-slot-desc">
    {t('ultimateSlot.description', 'Un Pokémon mentor transmet une partie de ses stats à chaque membre de l\'équipe. Il ne combat pas et ne gagne pas d\'XP.')}
  </p>

  <div class="ultimate-slot-transfer">
    <strong>{t('ultimateSlot.transferRate', 'Transfert')} : {transferPct}%</strong>
    <span class="ultimate-slot-transfer-hint">
      {t('ultimateSlot.shopHint', 'Améliorez la transmission au shop (Pokédollars).')}
    </span>
  </div>

  {#if team.ultimateSlot}
    <div class="ultimate-slot-mentor-row">
      <div class="ultimate-slot-mentor-left">
        <div class="ultimate-slot-mentor-visual">
          <img
            src={team.ultimateSlot.spriteUrl}
            alt=""
            class="ultimate-slot-mentor-sprite"
            width="96"
            height="96"
          />
          <div class="ultimate-slot-mentor-name">{team.ultimateSlot.displayName}</div>
          <div class="ultimate-slot-mentor-lvl">Lv.{team.ultimateSlot.level}</div>
        </div>
        <button type="button" class="sort-btn ultimate-slot-remove-btn" data-action="removeFromUltimateSlot">
          {t('ultimateSlot.remove', 'Retirer vers le stockage')}
        </button>
      </div>

      <div class="ultimate-slot-bonus-panel">
        <h3>{t('ultimateSlot.bonusPerMember', 'Bonus par membre d\'équipe')}</h3>
        <table class="ultimate-slot-bonus-table">
          <tbody>
            <tr><td>HP</td><td>+{bonus.hp}</td></tr>
            <tr><td>ATK</td><td>+{bonus.attack}</td></tr>
            <tr><td>SP.ATK</td><td>+{bonus.spattack}</td></tr>
            <tr><td>DEF</td><td>+{bonus.defense}</td></tr>
            <tr><td>SP.DEF</td><td>+{bonus.spdefense}</td></tr>
            <tr><td>SPD</td><td>+{bonus.speed}</td></tr>
          </tbody>
        </table>
      </div>
    </div>
  {:else}
    <div class="storage-header-row ultimate-slot-pick-section">
      <h3 class="ultimate-slot-pick-title">{t('ultimateSlot.select', 'Choisir depuis le stockage')}</h3>

      <div class="storage-controls">
        <StorageFiltersBar idPrefix="ultimate-" bind:filters={modalFilters} onFilterChange={() => { rosterTick += 1; }} />
        <StorageSortBar idPrefix="ultimate-" sortStack={team.storageSortStack} />
      </div>

      {#if pickCandidates.length === 0 && !pickShowEmptyFiltered}
        <p class="ultimate-slot-empty">{t('ultimateSlot.emptyStorage', 'Aucun Pokémon disponible dans le stockage.')}</p>
      {:else}
        <div class="storage-container">
          <div class="ultimate-slot-pick-scroll">
            <StorageGrid
              listId="ultimateSlotPickList"
              pickMode="ultimateSlot"
              forceSpriteOnly={true}
              creatures={pickCandidates}
              showEmptyFiltered={pickShowEmptyFiltered}
              scrollRootSelector=".ultimate-slot-pick-scroll"
              ultimateSlotBonusMaxima={pickTooltipScale.maxima}
              ultimateSlotBonusTotalMax={pickTooltipScale.totalMax}
            />
          </div>
        </div>
      {/if}
    </div>
  {/if}
</div>

